import java.nio.file.*;
import java.util.*;
import javax.tools.*;
import javax.lang.model.element.*;
import javax.lang.model.type.*;
import com.sun.source.tree.*;
import com.sun.source.util.*;
/** Full-source attributed callback census; analyze only, never emits incomplete mod classes. */
public final class ProjectileScanner {
 static final Set<String> ROOTS=new HashSet<>(Arrays.asList("EntityThrowableNT","EntityGrenadeBouncyBase","EntityBullet","EntityChopperMine","EntityRocket","EntityExplosiveBeam","EntitySchrab"));
 static final Set<String> NAMES=new HashSet<>(Arrays.asList("setThrowableHeading","shoot","setThrowableHeading2","headingForceMult"));
 static String q(Object o){return o==null?"null":"\""+o.toString().replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t")+"\"";}
 static String owner(Element e){return e==null?null:e.getEnclosingElement().toString();}
 static boolean target(Element e){if(!(e instanceof ExecutableElement))return false;ExecutableElement m=(ExecutableElement)e;String n=m.getSimpleName().toString();List<String> params=new ArrayList<>();for(VariableElement p:m.getParameters())params.add(p.asType().toString());return (n.equals("setThrowableHeading")||n.equals("shoot"))&&ROOTS.contains(m.getEnclosingElement().getSimpleName().toString())&&(m.getEnclosingElement().toString().equals("com.hbm.entity.projectile."+m.getEnclosingElement().getSimpleName())||m.getEnclosingElement().toString().equals("com.hbm.entity.grenade.EntityGrenadeBouncyBase"))&&!m.getModifiers().contains(Modifier.STATIC)&&m.getReturnType().toString().equals("void")&&params.equals(Arrays.asList("double","double","double","float","float"));}
 static boolean engineThrowable(TypeMirror t){while(t!=null&&t.getKind()==TypeKind.DECLARED){TypeElement e=(TypeElement)((DeclaredType)t).asElement();if(e.getQualifiedName().contentEquals("net.minecraft.entity.projectile.EntityThrowable"))return true;t=e.getSuperclass();}return false;}
 static boolean engineMethod(Element e){if(!(e instanceof ExecutableElement))return false;ExecutableElement m=(ExecutableElement)e;List<String> p=new ArrayList<>();for(VariableElement a:m.getParameters())p.add(a.asType().toString());return owner(e).equals("net.minecraft.entity.projectile.EntityThrowable")&&e.getSimpleName().contentEquals("shoot")&&!e.getModifiers().contains(Modifier.STATIC)&&p.equals(Arrays.asList("double","double","double","float","float"));}
 public static void main(String[] args)throws Exception{
  JavaCompiler c=ToolProvider.getSystemJavaCompiler();DiagnosticCollector<JavaFileObject> di=new DiagnosticCollector<>();StandardJavaFileManager fm=c.getStandardFileManager(di,null,null);
  JavacTask task=(JavacTask)c.getTask(null,fm,di,Arrays.asList("-proc:none","-source","8","-encoding","UTF-8","-classpath",new String(Files.readAllBytes(Paths.get(args[1]))).trim(),"-sourcepath","","-Xmaxerrs","100000"),null,fm.getJavaFileObjectsFromStrings(Files.readAllLines(Paths.get(args[0]))));
  Trees trees=Trees.instance(task);SourcePositions pos=trees.getSourcePositions();List<CompilationUnitTree> units=new ArrayList<>();for(CompilationUnitTree u:task.parse())units.add(u);for(Diagnostic<?> d:di.getDiagnostics())if(d.getKind()==Diagnostic.Kind.ERROR)throw new AssertionError("parse error "+d);task.analyze();
  for(CompilationUnitTree u:units){String source=u.getSourceFile().getCharContent(true).toString();new TreePathScanner<Void,Void>(){
   void emit(Tree t,String kind,String name,Element e,String type,boolean accept,long ns,long ne){long start=pos.getStartPosition(u,t),end=pos.getEndPosition(u,t);String raw=start>=0&&end>=start?source.substring((int)start,(int)end):"";if(raw.contains("\\"))accept=false;System.out.println("{\"path\":"+q(Paths.get(u.getSourceFile().toUri()))+",\"kind\":"+q(kind)+",\"name\":"+q(name)+",\"owner\":"+q(owner(e))+",\"element\":"+q(e)+",\"type\":"+q(type)+",\"accept\":"+accept+",\"start\":"+start+",\"end\":"+end+",\"ns\":"+ns+",\"ne\":"+ne+"}");}
   public Void visitClass(ClassTree t,Void v){Element e=trees.getElement(getCurrentPath());if(e instanceof TypeElement){TypeElement ce=(TypeElement)e;System.out.println("{\"path\":"+q(Paths.get(u.getSourceFile().toUri()))+",\"kind\":\"class\",\"name\":"+q(ce.getQualifiedName())+",\"parent\":"+q(ce.getSuperclass())+",\"interfaces\":"+q(ce.getInterfaces())+"}");}return super.visitClass(t,v);}
   public Void visitMethod(MethodTree t,Void v){String n=t.getName().toString();if(NAMES.contains(n)){Element e=trees.getElement(getCurrentPath());long s=pos.getStartPosition(u,t),end=pos.getEndPosition(u,t);String raw=source.substring((int)s,(int)end);int idx=raw.indexOf(n+"(");if(idx<0)idx=raw.indexOf(n+" (");emit(t,"declaration",n,e,null,target(e),s+idx,s+idx+n.length());}return super.visitMethod(t,v);}
   public Void visitMethodInvocation(MethodInvocationTree t,Void v){Tree sel=t.getMethodSelect();String n=sel instanceof MemberSelectTree?((MemberSelectTree)sel).getIdentifier().toString():sel.toString();if(NAMES.contains(n)){TreePath sp=new TreePath(getCurrentPath(),sel);Element e=trees.getElement(sp);String type=null;boolean accept=target(e);if(sel instanceof MemberSelectTree){TreePath rp=new TreePath(sp,((MemberSelectTree)sel).getExpression());type=String.valueOf(trees.getTypeMirror(rp));TypeMirror rt=trees.getTypeMirror(rp);if(rt!=null&&engineThrowable(rt)&&type.startsWith("com.hbm.entity.")&&t.getArguments().size()==5){if(n.equals("shoot"))accept=engineMethod(e);else if(n.equals("setThrowableHeading")&&rt.getKind()==TypeKind.DECLARED){boolean shadows=false,nativeFound=false;for(Element member:task.getElements().getAllMembers((TypeElement)((DeclaredType)rt).asElement())){if(member instanceof ExecutableElement&&member.getSimpleName().contentEquals("setThrowableHeading"))shadows=true;if(engineMethod(member))nativeFound=true;}accept=!shadows&&nativeFound;}}if(trees.getElement(rp) instanceof TypeElement)accept=false;}long ne=pos.getEndPosition(u,sel);emit(t,"call",n,e,type,accept,ne-n.length(),ne);}return super.visitMethodInvocation(t,v);}
  }.scan(u,null);}
  System.err.println("Units="+units.size()+"; expected incomplete-port analysis errors="+di.getDiagnostics().stream().filter(d->d.getKind()==Diagnostic.Kind.ERROR).count());fm.close();
 }
}
